import { useState,useEffect } from 'react';
import Phone from './Phones';
function Task(props) {

    const [tasks, setTasks] = useState([]);
    useEffect(() => {
    fetch(`http://localhost:5000/api/contacts/{props.id}/phones`)
    .then(response => response.json())
    .then(data => setTasks(data))
    .catch((error) => {
    console.error('Error:', error);
    });
    }, []);



	console.log(props);

	function onChange() {
		const updatedTask = {
		id: props.id,
		description: props.description,
		completed: !props.completed
		};
		fetch(`http://localhost:5000/api/contacts/${props.id}`, {
		method: 'PUT',
		headers: {
		'Content-Type': 'application/json'
		},
		body: JSON.stringify(updatedTask)
		})
		.then(response => response.json())
		.then(() => {
		props.setTasks(tasks => tasks.map(task => {
		if (task.id === props.id) {
		return updatedTask;
		} else {
		return task;
		}
		}));
		})
		.catch((error) => {
		console.error('Error:', error);
		});
		}

	function onClick() {
		// Find the task we want to delete and remove it
		fetch(`http://localhost:5000/api/contacts/${props.id}`,{
			method: 'DELETE',
		})
		.then(()=>{
			props.setTasks(tasks => tasks.filter(task => task.id !== props.id));
		})
		.catch((error) => {
			console.error('Error:', error);
		});


	}

	return (
		<li><button type="button" onClick={onClick} onChange={onchange}>Delete</button> { props.contactname }</li>


	);
}

function List(props) {

	const [newTask, setNewTask] = useState("");

	function onChange(event) {
		setNewTask(event.target.value);
	}

	function onClick() {
		fetch('http://localhost:5000/api/contacts/', {
		method: 'POST',
		headers: {
		'Content-Type': 'application/json'
		},
		body: JSON.stringify({ contactname: newTask })
		})
		.then(response => response.json())
		.then(data => {
		props.setTasks(tasks => [...tasks, data]);
		})
		.catch((error) => {
		console.error('Error:', error);
		});
		setNewTask(""); // Clear the input field
		}

	return (
		<div>
			<h1>{ props.heading }</h1>
			<input type="text" placeholder="Add a new task" onChange={onChange} />
			<button type="button" onClick={onClick}>Add</button>
			<ul>
				{ props.tasks.map(task => <Task setTasks={props.setTasks} id={task.id} contactname={task.contactname} />) }
			</ul>
		</div>
	);
}

export default List;
